diff --git a/server/services/identityGuard.reminderFlip.ts b/server/services/identityGuard.reminderFlip.ts
index 7bb5749..8756bbb 100644
--- a/server/services/identityGuard.reminderFlip.ts
+++ b/server/services/identityGuard.reminderFlip.ts
@@ -192,3 +192,103 @@ export function isReminderOriginOnlyFlip(previous: unknown, next: unknown): bool
   delete nClone.updatedAt;
   return JSON.stringify(pClone) === JSON.stringify(nClone);
 }
+
+/** Fields an agent-driven reminder EDIT (`remind update`, MCP `remind_update`) may change. */
+const REMINDER_EDITABLE_FIELDS = ['body', 'prompt', 'dueAt', 'priority', 'status', 'response', 'answeredAt'] as const;
+const REMINDER_PRIORITIES = ['low', 'normal', 'high', 'urgent'];
+
+/**
+ * Whether a SINGLE `kind: 'reminder'` item differs from its previous version
+ * ONLY by an edit an agent is allowed to author: text (`body`+`prompt`),
+ * `dueAt` (set, changed or cleared), `priority`, and the done/reopen
+ * transition. Same STRICT-equality discipline as `isSingleReminderDoneFlip`:
+ * every field outside `REMINDER_EDITABLE_FIELDS` must be byte-identical, and
+ * the status fields may only land on one of the two exact shapes `remind
+ * done` / a restore produce — never an arbitrary `response`.
+ */
+function isSingleReminderEdit(prevItem: unknown, nextItem: unknown): boolean {
+  if (
+    prevItem === null ||
+    nextItem === null ||
+    typeof prevItem !== 'object' ||
+    typeof nextItem !== 'object'
+  ) {
+    return false;
+  }
+  const p = prevItem as Record<string, unknown>;
+  const n = nextItem as Record<string, unknown>;
+
+  if (p.kind !== 'reminder' || n.kind !== 'reminder') return false;
+  if (p.id !== n.id || typeof p.id !== 'string') return false;
+
+  // Text: `body` stays a non-empty string (`prompt` is rewritten alongside it by `applyReminderPatch`).
+  if (typeof n.body !== 'string' || n.body.trim() === '' || typeof n.prompt !== 'string') return false;
+  // dueAt: absent or a parseable ISO datetime.
+  if (n.dueAt !== undefined && (typeof n.dueAt !== 'string' || Number.isNaN(Date.parse(n.dueAt)))) return false;
+  // priority: absent or one of the schema's literals.
+  if (n.priority !== undefined && !REMINDER_PRIORITIES.includes(n.priority as string)) return false;
+
+  // Status: exactly the two shapes `remind done` and a restore produce.
+  if (n.status === 'answered') {
+    if (n.response === null || typeof n.response !== 'object' || Array.isArray(n.response)) return false;
+    const keys = Object.keys(n.response as Record<string, unknown>);
+    if (keys.length !== 1 || keys[0] !== 'done' || (n.response as Record<string, unknown>).done !== true) return false;
+    if (typeof n.answeredAt !== 'string' || Number.isNaN(Date.parse(n.answeredAt))) return false;
+    // An already-answered reminder keeps its original answer timestamp.
+    if (p.status === 'answered' && n.answeredAt !== p.answeredAt) return false;
+  } else if (n.status === 'pending') {
+    if (n.response !== undefined || n.answeredAt !== undefined) return false;
+  } else {
+    return false;
+  }
+
+  const pClone = { ...p };
+  const nClone = { ...n };
+  for (const field of REMINDER_EDITABLE_FIELDS) {
+    delete pClone[field];
+    delete nClone[field];
+  }
+  return JSON.stringify(pClone) === JSON.stringify(nClone);
+}
+
+/**
+ * The edit counterpart of `isReminderDoneOnlyFlip`: whether `next` is
+ * `previous` with EXACTLY ONE `kind: 'reminder'` item edited (see
+ * `isSingleReminderEdit`) and nothing else in the conversation touched.
+ * Wired into `updateReminder` (`server/services/reminderStore.ts`), the
+ * shared write path of `remind update` and the MCP `remind_update` tool.
+ * FAIL-CLOSED by construction, identical shape to `isReminderDoneOnlyFlip`.
+ */
+export function isReminderEditOnlyFlip(previous: unknown, next: unknown): boolean {
+  if (
+    previous === null ||
+    next === null ||
+    typeof previous !== 'object' ||
+    typeof next !== 'object'
+  ) {
+    return false;
+  }
+  const p = previous as Record<string, unknown>;
+  const n = next as Record<string, unknown>;
+
+  const pItems = Array.isArray(p.items) ? p.items : null;
+  const nItems = Array.isArray(n.items) ? n.items : null;
+  if (!pItems || !nItems || pItems.length !== nItems.length) return false;
+
+  let changedIndex = -1;
+  for (let i = 0; i < pItems.length; i++) {
+    if (JSON.stringify(pItems[i]) === JSON.stringify(nItems[i])) continue;
+    if (changedIndex !== -1) return false;
+    changedIndex = i;
+  }
+  if (changedIndex === -1) return false;
+  if (!isSingleReminderEdit(pItems[changedIndex], nItems[changedIndex])) return false;
+
+  const pClone = { ...p };
+  const nClone = { ...n };
+  delete pClone.items;
+  delete nClone.items;
+  delete pClone.updatedAt;
+  delete nClone.updatedAt;
+  return JSON.stringify(pClone) === JSON.stringify(nClone);
+}
