---diff taskLaunchctl---

1	/**
2	 * Guarded launchctl invoker (security-critical) — the SINGLE choke point for
3	 * observing + driving the launchd daemons/jobs the External Tasks dashboard
4	 * supervises (second-brain-bridge, workstation itself, second-brain-mirror,
5	 * claude-skills-sync).
6	 *
7	 * Mirrors server/services/spawnExecutor.ts's hardening guarantees exactly:
8	 *
9	 *   - ARGUMENT ARRAY ONLY. `child_process.spawn(bin, args)` with `shell: false`.
10	 *     No shell string is ever constructed.
11	 *   - ALLOWLIST. Every call site must pass the set of labels the caller is
12	 *     actually allowed to touch (the labels of REGISTERED tasks); a label
13	 *     outside that set — or one that doesn't match `com.elmabi.<kebab>` — is
14	 *     rejected before any process is spawned.
15	 *   - TIMEOUT. The child is SIGKILL-ed if it overruns `timeoutMs` (default
16	 *     10s — launchctl calls are quick; a hang means launchd itself is wedged).
17	 *   - BOUNDED BUFFERS. stdout/stderr are capped; a runaway/hung `launchctl
18	 *     print` cannot exhaust memory.
19	 *   - MINIMAL ENV. PATH + HOME only — launchctl needs nothing else.
20	 *
21	 * `runLaunchctl` NEVER throws on a non-zero exit (a job that isn't loaded
22	 * makes `launchctl print` exit non-zero — that's an expected, handled case,
23	 * not a programming error) — only an un-allowlisted label rejects.
24	 *
25	 * We NEVER spawn a competing copy of the supervised task itself — only
26	 * `launchctl` is invoked, and only with `kickstart` / `kill` / `print`.
27	 */
28	import { spawn } from 'node:child_process';
29	
30	/* -------------------------------------------------------------------------- */
31	/*  Config                                                                    */
32	/* -------------------------------------------------------------------------- */
33	
34	/** Overridable via LAUNCHCTL_BIN so tests point at a fixture script instead
35	 *  of the real launchctl. NEVER call the real binary from a test.
36	 *  Default is `/bin/launchctl` — the canonical macOS location (there is NO
37	 *  `/usr/bin/launchctl`; using it made every daemon read as "not loaded"). */
38	export function launchctlBin(): string {
39	  return process.env.LAUNCHCTL_BIN ?? '/bin/launchctl';
40	}
41	
42	function home(): string {
43	  return process.env.HOME ?? process.env.USERPROFILE ?? '/Users/elmabi';
44	}
45	
46	/** `gui/<uid>/<label>` — the launchd domain target for a per-user GUI agent. */
47	export function guiTarget(label: string): string {
48	  return `gui/${process.getuid?.() ?? 0}/${label}`;
49	}
50	
51	/** Every allowlisted label MUST match this shape: our own reverse-DNS prefix,
52	 *  lowercase kebab-case name. Rejects anything else outright, independent of
53	 *  the caller-supplied allowlist (belt + suspenders). */
54	const LABEL_SHAPE_RE = /^com\.elmabi\.[a-z0-9-]+$/;
55	
56	/**
57	 * Reject a label that is not exactly one of `allowedLabels` (the labels of
58	 * REGISTERED tasks — never a caller-supplied arbitrary string) or that does
59	 * not match the `com.elmabi.<kebab>` shape. Throws on rejection; callers must
60	 * not proceed to spawn anything if this throws.
61	 */
62	export function assertAllowedLabel(label: string, allowedLabels: string[]): void {
63	  if (!LABEL_SHAPE_RE.test(label)) {
64	    throw new Error(`taskLaunchctl: refusing malformed label "${label}"`);
65	  }
66	  if (!allowedLabels.includes(label)) {
67	    throw new Error(`taskLaunchctl: label "${label}" is not on the allowlist`);
68	  }
69	}
