71	/* -------------------------------------------------------------------------- */
72	/*  Run                                                                       */
73	/* -------------------------------------------------------------------------- */
74	
75	export interface LaunchctlResult {
76	  code: number | null;
77	  stdout: string;
78	  stderr: string;
79	  timedOut: boolean;
80	}
81	
82	const DEFAULT_TIMEOUT_MS = 10_000;
83	const MAX_BUFFER_BYTES = 1 * 1024 * 1024;
84	
85	/**
86	 * Run `launchctl <args>` with a clean minimal env, a timeout, and bounded
87	 * buffers. NEVER throws on a non-zero exit or timeout — resolves with the
88	 * result either way, so callers (inspect/kickstart/kill) can branch on
89	 * `code`/`stdout` without try/catch noise. Only a spawn-level failure (e.g.
90	 * the binary is missing) is captured into `stderr` with `code: null`, same
91	 * as spawnExecutor.
92	 */
93	export function runLaunchctl(
94	  args: string[],
95	  timeoutMs: number = DEFAULT_TIMEOUT_MS,
96	): Promise<LaunchctlResult> {
97	  return new Promise((resolve) => {
98	    const child = spawn(launchctlBin(), args, {
99	      shell: false,
100	      env: {
101	        PATH: process.env.PATH ?? '/usr/bin:/bin',
102	        HOME: home(),
103	      },
104	      stdio: ['ignore', 'pipe', 'pipe'],
105	    });
106	
107	    let stdout = '';
108	    let stderr = '';
109	    let stdoutBytes = 0;
110	    let stderrBytes = 0;
111	    let timedOut = false;
112	    let settled = false;
113	
114	    const kill = () => {
115	      try {
116	        child.kill('SIGKILL');
117	      } catch {
118	        /* already gone */
119	      }
120	    };
121	
122	    const timer = setTimeout(() => {
123	      timedOut = true;
124	      kill();
125	    }, timeoutMs);
126	
127	    child.stdout.on('data', (chunk: Buffer) => {
128	      stdoutBytes += chunk.length;
129	      if (stdoutBytes <= MAX_BUFFER_BYTES) stdout += chunk.toString('utf8');
130	    });
131	    child.stderr.on('data', (chunk: Buffer) => {
132	      stderrBytes += chunk.length;
133	      if (stderrBytes <= MAX_BUFFER_BYTES) stderr += chunk.toString('utf8');
134	    });
135	
136	    const finish = (code: number | null) => {
137	      if (settled) return;
138	      settled = true;
139	      clearTimeout(timer);
140	      resolve({ code, stdout, stderr, timedOut });
141	    };
142	
143	    child.on('error', (err) => {
144	      if (!settled) {
145	        stderr += `\n[taskLaunchctl] spawn error: ${err instanceof Error ? err.message : String(err)}`;
146	        finish(null);
147	      }
148	    });
149	
150	    child.on('close', (code) => finish(code));
151	  });
152	}
153	
154	/* -------------------------------------------------------------------------- */
155	/*  Helpers                                                                   */
156	/* -------------------------------------------------------------------------- */
157	
158	/**
159	 * `launchctl kickstart [-k] gui/<uid>/<label>`. Without `-k`: start the job if
160	 * it isn't running (used to trigger an immediate run of a `scheduled` job).
161	 * With `-k`: kill-then-restart (used for a `daemon`'s start/restart — a
162	 * daemon under KeepAlive is normally already running, so an unconditional
163	 * restart is what "start" means for it too).
164	 */
165	export function kickstart(label: string, opts?: { restart?: boolean }): Promise<LaunchctlResult> {
166	  const args = ['kickstart'];
167	  if (opts?.restart) args.push('-k');
168	  args.push(guiTarget(label));
169	  return runLaunchctl(args);
170	}
171	
172	/** `launchctl kill <signal> gui/<uid>/<label>` — best-effort stop. Note:
173	 *  KeepAlive daemons are relaunched by launchd almost immediately; this is a
174	 *  deliberate, documented limitation (see task description), not a bug. */
175	export function killSignal(label: string, signal: string = 'SIGTERM'): Promise<LaunchctlResult> {
176	  return runLaunchctl(['kill', signal, guiTarget(label)]);
177	}
178	
179	export interface LaunchctlState {
180	  loaded: boolean;
181	  running: boolean;
182	  pid?: number;
183	  lastExitCode?: number | null;
184	}
185	
186	/**
187	 * `launchctl print gui/<uid>/<label>` and parse the fields we care about.
188	 * Tolerant regexes: macOS's `print` output format has shifted across OS
189	 * versions, so we match loosely (`state = running`, `pid = 1234`,
190	 * `last exit code = 0`) rather than assuming an exact layout.
191	 *
192	 * If the job isn't loaded, `launchctl print` exits non-zero — we treat that
193	 * as `{ loaded: false }` rather than an error (an unloaded job is a valid,
194	 * expected state: e.g. right after `launchctl bootout`).
195	 */
196	export async function printState(label: string): Promise<LaunchctlState> {
197	  const result = await runLaunchctl(['print', guiTarget(label)]);
198	  if (result.code !== 0) {
199	    return { loaded: false, running: false };
200	  }
201	
202	  const stateMatch = result.stdout.match(/state\s*=\s*(\S+)/i);
203	  const pidMatch = result.stdout.match(/\bpid\s*=\s*(\d+)/i);
204	  const exitMatch = result.stdout.match(/last exit code\s*=\s*(-?\d+)/i);
205	
206	  const state = stateMatch?.[1]?.toLowerCase();
207	  const running = state === 'running';
208	  const pid = pidMatch ? Number(pidMatch[1]) : undefined;
209	  const lastExitCode = exitMatch ? Number(exitMatch[1]) : undefined;
210	
211	  return {
212	    loaded: true,
213	    running,
214	    pid: running ? pid : undefined,
215	    lastExitCode,
216	  };
217	}
218	
219	/** Convenience wrapper matching the spec's requested `inspect()` name. */
220	export function inspect(label: string): Promise<LaunchctlState> {
221	  return printState(label);
222	}
