1	import { spawn } from 'node:child_process';
2	import fs from 'node:fs/promises';
3	import os from 'node:os';
4	import path from 'node:path';
5	
6	import type { ExternalTask, ExternalTaskKind, ExternalTaskProject } from '../../src/types/task';
7	import { projectsRoot } from '../config';
8	import { slugify } from './slug';
9	import { createTask, findTask, getTask, listTasks, taskExists } from './taskStore';
10	
11	/**
12	 * Auto-discovery of launchd LaunchAgents (Operations › Daemons & jobs).
13	 *
14	 * `taskSeed.ts` hardcodes an inventory; any job installed AFTER it was written
15	 * (e.g. `com.elmabi.pplab-solution-snapshot`, `com.elmabi.me-ask-autoupdate`)
16	 * stayed invisible to the dashboard, the health loop and therefore to the
17	 * failure alerter. This module scans `~/Library/LaunchAgents/com.elmabi.*.plist`
18	 * (overridable: `WORKSTATION_LAUNCHAGENTS_DIR`), parses each plist with
19	 * `plutil -convert json -o - <file>` and CREATES a task for every label that is
20	 * not registered yet.
21	 *
22	 * Guarantees:
23	 *  - READ-ONLY on the LaunchAgents dir. Only `plutil` is spawned (argument
24	 *    array, `shell: false`, minimal env, timeout, bounded buffers — the same
25	 *    hardening as taskLaunchctl.ts). The job itself is NEVER executed; the
26	 *    `command` field is display-only.
27	 *  - NEVER overwrites an existing task: a label already carried by a task, an
28	 *    id already used, or an existing `<slug>/<id>.json` is skipped.
29	 *  - `EnvironmentVariables` → NAMES ONLY (`envVarNames`). Values are dropped
30	 *    in memory right after parsing: never stored, never logged.
31	 *  - Only `*.plist` whose name starts with `com.elmabi.` (a
32	 *    `com.elmabi.workstation.plist.bak-20260723` is ignored) and whose `Label`
33	 *    matches the task schema regex.
34	 */
35	
36	/* -------------------------------------------------------------------------- */
37	/*  Config                                                                    */
38	/* -------------------------------------------------------------------------- */
39	
40	const LABEL_RE = /^com\.elmabi\.[a-z0-9-]+$/;
41	const LABEL_PREFIX = 'com.elmabi.';
42	const PLUTIL_TIMEOUT_MS = 10_000;
43	const MAX_PLUTIL_OUTPUT_BYTES = 1024 * 1024;
44	const DEFAULT_DISCOVERY_INTERVAL_MS = 10 * 60 * 1000;
45	
46	function home(): string {
47	  return process.env.HOME ?? os.homedir();
48	}
49	
50	/** Scanned directory — call-time env read so a test can point it at a fixture dir. */
51	export function launchAgentsDir(): string {
52	  return process.env.WORKSTATION_LAUNCHAGENTS_DIR ?? path.join(home(), 'Library', 'LaunchAgents');
53	}
54	
55	/** `plutil` binary — overridable via PLUTIL_BIN (tests use the real one). */
56	export function plutilBin(): string {
57	  return process.env.PLUTIL_BIN ?? '/usr/bin/plutil';
58	}
59	
60	/* -------------------------------------------------------------------------- */
61	/*  plutil                                                                    */
62	/* -------------------------------------------------------------------------- */
63	
64	export type PlistDict = Record<string, unknown>;
65	
66	/**
67	 * `plutil -convert json -o - <file>` → parsed object, or null on any failure
68	 * (non-zero exit, timeout, oversized output, invalid JSON — e.g. a plist with
69	 * `<date>`/`<data>` values plutil refuses to render as JSON). Never throws.
70	 * The raw stdout may carry environment VALUES: it is parsed and dropped here,
71	 * never logged.
72	 */
73	export function readPlist(file: string): Promise<PlistDict | null> {
74	  return new Promise((resolve) => {
75	    let child: ReturnType<typeof spawn>;
76	    try {
77	      child = spawn(plutilBin(), ['-convert', 'json', '-o', '-', file], {
78	        shell: false,
79	        env: { PATH: '/usr/bin:/bin', HOME: home() },
80	        stdio: ['ignore', 'pipe', 'ignore'],
81	      });
82	    } catch {
83	      resolve(null);
84	      return;
85	    }
86	
87	    let stdout = '';
88	    let bytes = 0;
89	    let overflow = false;
90	    let settled = false;
91	    const finish = (value: PlistDict | null) => {
92	      if (settled) return;
93	      settled = true;
94	      clearTimeout(timer);
95	      resolve(value);
96	    };
97	    const timer = setTimeout(() => {
98	      try {
99	        child.kill('SIGKILL');
100	      } catch {
101	        /* already gone */
102	      }
103	      finish(null);
104	    }, PLUTIL_TIMEOUT_MS);
105	
106	    child.stdout?.on('data', (chunk: Buffer) => {
107	      bytes += chunk.length;
108	      if (bytes > MAX_PLUTIL_OUTPUT_BYTES) {
109	        overflow = true;
110	        return;
111	      }
112	      stdout += chunk.toString('utf8');
113	    });
114	    child.on('error', () => finish(null));
115	    child.on('close', (code) => {
116	      if (code !== 0 || overflow) {
117	        finish(null);
118	        return;
119	      }
120	      try {
121	        const parsed: unknown = JSON.parse(stdout);
122	        finish(parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? (parsed as PlistDict) : null);
123	      } catch {
124	        finish(null);
125	      }
126	    });
127	  });
128	}
