130	/* -------------------------------------------------------------------------- */
131	/*  Pure derivations                                                          */
132	/* -------------------------------------------------------------------------- */
133	
134	function isInt(v: unknown, min: number, max: number): v is number {
135	  return typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;
136	}
137	
138	function range(from: number, to: number): number[] {
139	  const out: number[] = [];
140	  for (let i = from; i <= to; i++) out.push(i);
141	  return out;
142	}
143	
144	function calendarEntries(value: unknown): PlistDict[] {
145	  const raw = Array.isArray(value) ? value : value && typeof value === 'object' ? [value] : [];
146	  return raw.filter((e): e is PlistDict => Boolean(e) && typeof e === 'object' && !Array.isArray(e));
147	}
148	
149	function hasSchedule(plist: PlistDict): boolean {
150	  return plist.StartCalendarInterval !== undefined || plist.StartInterval !== undefined;
151	}
152	
153	function isKeepAlive(plist: PlistDict): boolean {
154	  const k = plist.KeepAlive;
155	  if (k === true) return true;
156	  return Boolean(k) && typeof k === 'object' && Object.keys(k as object).length > 0;
157	}
158	
159	const MINUTES_PER_WEEK = 7 * 24 * 60;
160	
161	/**
162	 * Expected max gap between two runs, in hours — the LARGEST gap of the
163	 * schedule, never an average, so an uneven schedule is never falsely "late"
164	 * (taskManager flags late beyond `expectedIntervalHours * 1.25`).
165	 *
166	 *  - `StartInterval` (seconds) → seconds / 3600.
167	 *  - `StartCalendarInterval` without `Day`/`Month`: every entry is expanded to
168	 *    its occurrences over one week (a missing `Weekday`/`Hour`/`Minute` means
169	 *    "every"), and the largest circular gap between consecutive occurrences is
170	 *    returned. 02:30 + 14:30 daily → 12 h ; Mon/Wed/Fri 04:30 → 72 h (Fri→Mon).
171	 *  - With `Day` → 31 × 24 h (monthly), with `Month` → 366 × 24 h (yearly):
172	 *    conservative on purpose.
173	 *  - No schedule, or nothing parseable → undefined (no lateness check).
174	 */
175	export function deriveExpectedIntervalHours(plist: PlistDict): number | undefined {
176	  if (typeof plist.StartInterval === 'number' && plist.StartInterval > 0) {
177	    return Math.round((plist.StartInterval / 3600) * 100) / 100;
178	  }
179	  if (plist.StartCalendarInterval === undefined) return undefined;
180	
181	  const entries = calendarEntries(plist.StartCalendarInterval);
182	  if (entries.length === 0) return undefined;
183	  if (entries.some((e) => e.Month !== undefined)) return 366 * 24;
184	  if (entries.some((e) => e.Day !== undefined)) return 31 * 24;
185	
186	  const occurrences = new Set<number>();
187	  for (const e of entries) {
188	    // launchd accepts 0 and 7 for Sunday.
189	    const weekdays = e.Weekday === undefined ? range(0, 6) : isInt(e.Weekday, 0, 7) ? [e.Weekday % 7] : [];
190	    const hours = e.Hour === undefined ? range(0, 23) : isInt(e.Hour, 0, 23) ? [e.Hour] : [];
191	    const minutes = e.Minute === undefined ? range(0, 59) : isInt(e.Minute, 0, 59) ? [e.Minute] : [];
192	    for (const wd of weekdays) {
193	      for (const h of hours) {
194	        for (const m of minutes) occurrences.add(wd * 1440 + h * 60 + m);
195	      }
196	    }
197	  }
198	  if (occurrences.size === 0) return undefined;
199	
200	  const sorted = [...occurrences].sort((a, b) => a - b);
201	  let maxGap = sorted[0] + MINUTES_PER_WEEK - sorted[sorted.length - 1];
202	  for (let i = 1; i < sorted.length; i++) {
203	    maxGap = Math.max(maxGap, sorted[i] - sorted[i - 1]);
204	  }
205	  return Math.round((maxGap / 60) * 100) / 100;
206	}
207	
208	/** `scheduled` when the plist has a schedule; `daemon` only for KeepAlive. A
209	 *  RunAtLoad-only (or on-demand) job runs once and exits — as a `daemon` it
210	 *  would read "chargé mais aucun PID actif" forever (a false alarm), so it is
211	 *  modelled as a `scheduled` job without expected interval (health = last exit
212	 *  code only). */
213	export function deriveKind(plist: PlistDict): ExternalTaskKind {
214	  if (hasSchedule(plist)) return 'scheduled';
215	  return isKeepAlive(plist) ? 'daemon' : 'scheduled';
216	}
217	
218	function programArguments(plist: PlistDict): string[] {
219	  const args = Array.isArray(plist.ProgramArguments)
220	    ? plist.ProgramArguments.filter((a): a is string => typeof a === 'string')
221	    : [];
222	  if (args.length > 0) return args;
223	  return typeof plist.Program === 'string' ? [plist.Program] : [];
224	}
225	
226	function displayCommand(args: string[]): string {
227	  return args.map((a) => (/\s/.test(a) || a === '' ? `"${a}"` : a)).join(' ');
228	}
229	
230	function cwdArgument(args: string[]): string | undefined {
231	  for (let i = 0; i < args.length; i++) {
232	    if (args[i] === '--cwd' && typeof args[i + 1] === 'string') return args[i + 1];
233	    if (args[i].startsWith('--cwd=')) return args[i].slice('--cwd='.length);
234	  }
235	  return undefined;
236	}
237	
238	/** The repo under PROJECTS_ROOT the job belongs to, from the first candidate
239	 *  path (workingDir, then ProgramArguments, then log paths) that lives there. */
240	export function inferProject(candidates: string[]): ExternalTaskProject | null {
241	  const base = path.resolve(projectsRoot());
242	  for (const c of candidates) {
243	    if (!c || !path.isAbsolute(c)) continue;
244	    const resolved = path.resolve(c);
245	    if (!resolved.startsWith(`${base}${path.sep}`)) continue;
246	    const segment = resolved.slice(base.length + 1).split(path.sep)[0];
247	    if (!segment || segment.startsWith('.')) continue;
248	    return { slug: slugify(segment), name: segment, path: path.join(base, segment) };
249	  }
250	  return null;
251	}
252	
253	function titleFromId(id: string): string {
254	  const words = id.split('-').filter(Boolean);
255	  if (words.length === 0) return id;
256	  const [first, ...rest] = words;
257	  return [first.charAt(0).toUpperCase() + first.slice(1), ...rest].join(' ');
258	}
259	
260	function scheduleSummary(plist: PlistDict, kind: ExternalTaskKind, expected?: number): string {
261	  if (typeof plist.StartInterval === 'number') return `StartInterval ${plist.StartInterval} s`;
262	  if (plist.StartCalendarInterval !== undefined) {
263	    const n = calendarEntries(plist.StartCalendarInterval).length;
264	    return `StartCalendarInterval, ${n} créneau${n > 1 ? 'x' : ''}${
265	      expected !== undefined ? `, écart max ${expected} h` : ''
266	    }`;
267	  }
268	  if (kind === 'daemon') return 'KeepAlive (daemon)';
269	  return plist.RunAtLoad === true ? 'RunAtLoad seul (exécuté au chargement)' : 'à la demande';
270	}
271	
272	/**
273	 * Pure mapping plist → ExternalTask (no I/O). Returns null when the plist has
274	 * no valid `Label`. `file` is only used for the description.
275	 */
276	export function buildTaskFromPlist(plist: PlistDict, file: string, nowIso: string): ExternalTask | null {
277	  const label = plist.Label;
278	  if (typeof label !== 'string' || !LABEL_RE.test(label)) return null;
279	
280	  const id = label.slice(LABEL_PREFIX.length);
281	  const args = programArguments(plist);
282	  const command = displayCommand(args) || label;
283	  const workingDir =
284	    typeof plist.WorkingDirectory === 'string' && plist.WorkingDirectory
285	      ? plist.WorkingDirectory
286	      : cwdArgument(args);
287	  const logPaths = [plist.StandardOutPath, plist.StandardErrorPath].filter(
288	    (p, i, all): p is string => typeof p === 'string' && p.length > 0 && all.indexOf(p) === i,
289	  );
290	  // NAMES ONLY — the values never leave this expression.
291	  const env = plist.EnvironmentVariables;
292	  const envVarNames =
293	    env && typeof env === 'object' && !Array.isArray(env) ? Object.keys(env).filter((k) => k.length > 0) : [];
294	
295	  const kind = deriveKind(plist);
296	  const derivedIntervalHours = kind === 'scheduled' ? deriveExpectedIntervalHours(plist) : undefined;
297	  // Lateness is judged on LOG FRESHNESS (taskManager: last log mtime). Only a
298	  // job wrapped by run-with-markers.sh is guaranteed to write its logs on
299	  // every run (RUN START/END markers); a job that prints nothing (e.g.
300	  // me-ask-autoupdate, empty launchd.*.log) would read "EN RETARD" after one
301	  // interval although it ran fine — a false alert. So the interval is only
302	  // ENFORCED for marker-wrapped jobs; otherwise it is documented in the
303	  // description and failure detection relies on the exit code alone.
304	  const usesRunMarkers = args.some((a) => path.basename(a) === 'run-with-markers.sh');
305	  const expectedIntervalHours = usesRunMarkers ? derivedIntervalHours : undefined;
306	  const project = inferProject([workingDir ?? '', ...args, ...logPaths]) ?? {
307	    slug: 'launchd',
308	    name: 'launchd',
309	    path: launchAgentsDir(),
310	  };
311	
312	  return {
313	    schemaVersion: 1,
314	    id,
315	    project,
316	    title: titleFromId(id),
317	    description:
318	      `Découvert automatiquement depuis le plist ${path.basename(file)} (${path.dirname(file)}). ` +
319	      `Planification : ${scheduleSummary(plist, kind, derivedIntervalHours)}. ` +
320	      (derivedIntervalHours !== undefined && expectedIntervalHours === undefined
321	        ? 'Retard non surveillé : sans marqueurs run-with-markers.sh, la fraîcheur des logs ne prouve pas ' +
322	          `qu'un run a eu lieu — renseigner expectedIntervalHours (${derivedIntervalHours}) à la main si ` +
323	          'le job écrit dans ses logs à chaque run. '
324	        : '') +
325	      'Tâche éditable : la découverte ne réécrit jamais une tâche existante.',
326	    kind,
327	    launchdLabel: label,
328	    command,
329	    ...(workingDir ? { workingDir } : {}),
330	    logPaths,
331	    envVarNames,
332	    status: 'idle',
333	    healthCheckIntervalMs: 30000,
334	    autoRestart: kind === 'daemon',
335	    ...(expectedIntervalHours !== undefined ? { expectedIntervalHours } : {}),
336	    health: {},
337	    createdAt: nowIso,
338	    updatedAt: nowIso,
339	  };
340	}
