/**
 * Identity guard — the load-bearing security boundary of the intelligence loop.
 *
 * THE INVARIANT (Phase 4 exit criterion): an agent / MCP-authored write to the
 * decision hub may AUTHOR questions and approvals (items WITHOUT a `response`)
 * and may flip `agentFollowupStatus` to `'handled'`, but it must NEVER author an
 * ANSWER — most critically an `approval.response.decision`. The loop cannot be
 * allowed to satisfy its own HumanGate. Only a human (the dashboard UI, where
 * `actor` is the user) may write a response.
 *
 * This is a DETERMINISTIC, pure check (no I/O, fully unit-testable). It inspects
 * a conversation body about to be persisted and, for `actor === 'claude'`,
 * rejects the write if ANY item carries a `response`. It is wired into:
 *   1. the MCP `capture_gate` path (gate CREATION — responses forbidden), and
 *   2. exposed so the `convo` CLI write path can enforce it for actor='claude'.
 *
 * The human write path (the HTTP PUT from the dashboard) is actor='user' and is
 * NOT gated here — that is exactly where a legitimate `response.decision` lands.
 */

import { findOffendingItemIds } from './identityGuard.exemptions';

export { isReminderDoneOnlyFlip, isReminderEditOnlyFlip, isReminderOriginOnlyFlip } from './identityGuard.reminderFlip';

/** Who is attempting the write. The loop is `'claude'`; the dashboard is `'user'`. */
export type WriteActor = 'claude' | 'user';

export type IdentityGuardResult =
  | { allowed: true }
  | { allowed: false; reason: string; offendingItemIds: string[] };

/**
 * Inspect a conversation body for an actor. Returns `{ allowed: true }` for the
 * human path unconditionally; for the agent path, rejects if any item authors a
 * response (or the conversation is flagged completed/answered with a timestamp).
 *
 * The body is treated as untrusted/unparsed JSON (the guard runs BEFORE schema
 * validation so a forged shape is still caught), so every access is defensive.
 *
 * `opts.allowMirrorWrite` is the P19 CAPABILITY gate (default `false`): the
 * P19 mirror exemption in `itemHasResponse`/`isServerAuthoredDecisionMirror`
 * is kind-gated, schema-gated, AND marker-gated, but none of that is
 * sufficient on its own — a well-formed, marker-carrying mirror response is a
 * SELF-CERTIFYING claim of provenance (the body claims "a human already
 * decided this"), and nothing in the body's shape can prove who is allowed to
 * make that claim. Only `cmdMirrorResolution` (`server/cli/convo.ts`) sets
 * `allowMirrorWrite: true`; every other call site (`cmdCreate`, `cmdAddItem`,
 * MCP `capture_gate`) must keep the safe default — otherwise any untrusted
 * writer could forge the marker and have it waved through identically to a
 * verified mirror write.
 *
 * SCOPE OF THE GUARANTEE — read precisely, UPDATED post-D3 (chantier
 * mirror-self-verify, 2026-08-06): `cmdMirrorResolution` itself now
 * INDEPENDENTLY verifies against Convex before writing (see
 * `server/cli/convoMirrorSelfVerify.ts`, called from `convo.ts` as the LAST
 * gate before `saveConversation`) — it no longer merely trusts a
 * caller-asserted `allowMirrorWrite: true`. A forged `--decision`/
 * `--selected-option`/`--correction-note` is refused fail-closed unless a
 * self-verify HTTP call to second-brain's PROD
 * deployment confirms it matches the real Convex resolution. This closes the
 * SPECIFIC vector previously described here: a local, Bash-capable actor
 * (including an autonomous Claude Code session) invoking
 * `bun run convo mirror-resolution` by hand with a fabricated decision can no
 * longer make it write without Convex agreeing.
 *
 * What D3 does NOT close (still open, unrelated to this guard): a strictly
 * EASIER bypass of the same HumanGate invariant exists independently of this
 * mirror system entirely — `brain approvals resolve <id> --outcome ...`
 * (`cli/commands/approvals.ts` in second-brain) calls
 * `internal.core.approvals.resolve` directly, no marker/schema/self-verify
 * needed. Tracked as DEFERRED-014 in `second-brain/docs/backlog-deferred.html`
 * (a different repo — this file lives in workstation). The outer Claude Code
 * permission/consent layer remains the actual control against that bypass.
 */
export function checkConversationWrite(
  body: unknown,
  actor: WriteActor,
  opts?: { allowMirrorWrite?: boolean },
): IdentityGuardResult {
  // The human (dashboard) path is where responses legitimately land.
  if (actor === 'user') return { allowed: true };

  const allowMirrorWrite = opts?.allowMirrorWrite ?? false;

  if (body === null || typeof body !== 'object') {
    // Nothing to author a response on; let schema validation reject malformed
    // bodies downstream.
    return { allowed: true };
  }
  const conv = body as Record<string, unknown>;

  const items = Array.isArray(conv.items) ? conv.items : [];
  const offending = findOffendingItemIds(items, conv.answeredAt, allowMirrorWrite);

  if (offending.length > 0) {
    return {
      allowed: false,
      reason:
        'identity guard: an agent/MCP write may author questions/approvals ' +
        '(items WITHOUT a response) and may set agentFollowupStatus=handled, ' +
        'but it must NEVER author an answer/decision. ' +
        `Offending item(s): ${offending.join(', ')}. ` +
        'Only the human (dashboard) may write a response.',
      offendingItemIds: offending,
    };
  }

  return { allowed: true };
}

/**
 * Convenience assertion: throws an `Error` with the guard reason when the write
 * is forbidden. Used by call sites (CLI / MCP) that prefer a throw to a result.
 */
export function assertConversationWriteAllowed(
  body: unknown,
  actor: WriteActor,
  opts?: { allowMirrorWrite?: boolean },
): void {
  const verdict = checkConversationWrite(body, actor, opts);
  if (!verdict.allowed) {
    throw new Error(verdict.reason);
  }
}

/**
 * Whether flipping ONLY `agentFollowupStatus` to 'handled' is a legitimate agent
 * write (it is — the loop marks a followup handled after re-reading answers).
 * This is the one mutation the agent path is allowed to make on an
 * already-answered conversation. We expose it so a caller can distinguish a
 * `handled` flip (allowed) from a response smuggle (rejected): a `handled` flip
 * keeps every existing response untouched, which the guard above does NOT count
 * as authoring (the responses were authored by the human, not this write).
 *
 * NOTE: the guard intentionally rejects a body that carries item responses even
 * on a `handled` flip IF those responses originate from the agent path. The CLI
 * `handled` command echoes the existing on-disk conversation (responses authored
 * by the human) — so to keep that legitimate flow working, the CLI passes
 * `actor='user'` for the echo OR uses `markHandledAllowed` semantics. To avoid
 * coupling, the convo CLI uses a dedicated handled path that does not re-author

 * SINGLE definition of "en retard" (pending + `dueAt` present + parseable +
 * in the past) — shared by `hubPulse.ts`'s reminders widget AND
 * `speakerService.ts`'s overdue-announcement tick, so the two never drift
 * into two copies of the same predicate (same discipline this module's own
 * header claims for "what are the pending reminders"). Pure — no I/O, safe
 * to import from a pure-math module like `hubPulse.ts`'s `computePulse`.
 */
export function isReminderOverdue(item: { status: string; dueAt?: string }, now: number): boolean {
  if (item.status !== 'pending' || !item.dueAt) return false;
  const due = Date.parse(item.dueAt);
  return !Number.isNaN(due) && due < now;
}

/**
 * Locates a reminder BY ID across the whole `_reminders` conversation —
 * `pending` OR `answered` — so `remind read <id>` and `remind done <id>` can
 * both find an item regardless of where it sits in its lifecycle. Returns the
 * parent conversation alongside the item so a caller (e.g. `remind done`) can
 * build the next conversation body without a second read (and therefore
 * without racing the on-disk file between the two reads).
 */
export async function findReminderById(
  id: string,
): Promise<{ conversation: Conversation; item: ReminderItem } | null> {
  const conversation = await getRemindersConversation();
  if (!conversation) return null;
  const item = conversation.items.find(
    (it): it is ReminderItem => it.kind === 'reminder' && it.id === id,
  );
