/* -------------------------------------------------------------------------- */

export type StampReminderOriginResult =
  | { kind: 'not-found' }
  | { kind: 'unchanged'; item: ReminderItem }
  | { kind: 'stamped'; item: ReminderItem }
  | { kind: 'error'; error: unknown };

/**
 * Upgrade ONE reminder item's `origin` via `mergeOrigin` (the higher-
 * `capturedBy`-ranked of the on-disk origin and `incomingOrigin` wins —
 * `server/lib/agentOrigin.ts`) — the item-level counterpart of
 * `stampConversationOrigin`/`stampChipOrigin` for a record that is an ITEM
