 * exact origin already on disk — a replayed/late hook invocation, or a
 * `backfill-origin` re-run, is therefore always safe to re-run.
 */
export async function stampReminderOrigin(
  itemId: string,
  incomingOrigin: AgentOrigin,
): Promise<StampReminderOriginResult> {
  const found = await findReminderById(itemId);
  if (!found) return { kind: 'not-found' };
  const { conversation, item } = found;

  const merged = mergeOrigin(item.origin, incomingOrigin);
  if (JSON.stringify(merged) === JSON.stringify(item.origin)) {
    return { kind: 'unchanged', item };
  }

  const nextItem: ReminderItem = { ...item, origin: merged };
  const nextItems = conversation.items.map((it) => (it.id === itemId ? nextItem : it));
