  // write — same convention as `stampConversationOrigin`/`remind done`.
  const nextConversation: Conversation = { ...conversation, items: nextItems };

  if (!isReminderOriginOnlyFlip(conversation, nextConversation)) {
    return {
      kind: 'error',
      error:
        'identity guard: le delta construit pour stamp-origin ne correspond pas exactement au ' +
        "flip autorisé (origin d'un seul item kind:'reminder' changé, rien d'autre) — écriture refusée.",
