  if (!result.ok) return { kind: 'error', error: saveFailureReason(result) };

  const written = result.conversation.items.find(
    (it): it is ReminderItem => it.kind === 'reminder' && it.id === itemId,
  );
  return { kind: 'stamped', item: written ?? nextItem };
}

