/**
 * Human-readable reason for a failed SaveResult — collapses the secret-block
 * variant (which carries `patterns`, not `error`) and the generic error variant
 * into one message. Lets non-HTTP callers (CLI, MCP, the research/migration
 * gates) stay one-liners while the new discriminated variant keeps type safety.
 */
export function saveFailureReason(result: Exclude<SaveResult, { ok: true }>): string {
  if ('secretBlocked' in result) {
    return `secret en clair détecté (${result.patterns.join(', ')}) — écriture refusée`;
  }
  return typeof result.error === 'string' ? result.error : JSON.stringify(result.error);
}

