  inputSchema: I;
  /** zod schema the handler result MUST satisfy (validated before return). */
  outputSchema: O;
  /** Optional annotations (e.g. readOnlyHint) passed to registerTool. */
  annotations?: Record<string, unknown>;
  /** Per-tool rate-limit override. */
  rateLimit?: RateLimitConfig;
  /** Per-tool timeout override (ms). */
  timeoutMs?: number;
  /** The pure handler: receives validated args, returns the output payload. */
  handler: (args: z.infer<z.ZodObject<I>>) => Promise<z.infer<O>>;
