/** The launchd labels of every currently REGISTERED task — the only labels
 *  taskLaunchctl is ever allowed to touch. Recomputed per call so a freshly
 *  created/deleted task is reflected immediately (the store is the source of
 *  truth, not a cached list). */
async function registeredLabels(): Promise<string[]> {
  const metas = await listTasks();
  const labels: string[] = [];
  await Promise.all(
    metas.map(async (m) => {
      const task = await getTask(m.project.slug, m.id);
      if (task) labels.push(task.launchdLabel);
    }),
  );
  return labels;
}

async function resolveTask(slug: string | undefined, id: string): Promise<ExternalTask | null> {
  if (slug) {
    const task = await getTask(slug, id);
    if (task) return task;
  }
  return findTask(id);
}

