import { useCallback, useRef, useState } from 'react';

/**
 * État React adossé à `localStorage` (préférence durable) ou `sessionStorage`
 * (confort de l'onglet courant).
 *
 * - Lecture UNE fois, dans l'initialiseur paresseux de `useState` : aucun
 *   effet, donc aucune dépendance à surveiller (`.claude/rules/react-effects.md`).
 * - Toute valeur relue passe par `parse`, qui DOIT valider et retomber sur un
 *   défaut : une valeur corrompue ou d'une ancienne version ne casse jamais le
 *   rendu.
 * - Chaque accès au storage est protégé par try/catch : navigation privée
 *   stricte, quota plein ou storage bloqué dégradent vers l'état en mémoire.
 *
 * `parse` et `serialize` doivent être des fonctions stables (niveau module) :
 * elles entrent dans les dépendances du setter.
 */
export type StoredStateArea = 'local' | 'session';

export type StoredStateSetter<T> = (next: T | ((prev: T) => T)) => void;

function storageFor(area: StoredStateArea): Storage | null {
  try {
    if (typeof window === 'undefined') return null;
    return area === 'local' ? window.localStorage : window.sessionStorage;
  } catch {
    return null;
  }
}

export function readStoredRaw(area: StoredStateArea, key: string): string | null {
  try {
    return storageFor(area)?.getItem(key) ?? null;
  } catch {
    return null;
  }
}

export function writeStoredRaw(area: StoredStateArea, key: string, value: string): void {
