export function useStoredState<T>(
  area: StoredStateArea,
  key: string,
  parse: (raw: string | null) => T,
  serialize: (value: T) => string,
): [T, StoredStateSetter<T>] {
  const [value, setValue] = useState<T>(() => parse(readStoredRaw(area, key)));
  // Miroir synchrone de la dernière valeur écrite : deux appels successifs
  // dans le même tick composent au lieu de repartir d'un `value` périmé.
  const latest = useRef(value);

  const set = useCallback<StoredStateSetter<T>>(
    (next) => {
      const resolved =
        typeof next === 'function' ? (next as (prev: T) => T)(latest.current) : next;
      latest.current = resolved;
      setValue(resolved);
      writeStoredRaw(area, key, serialize(resolved));
    },
    [area, key, serialize],
  );

  return [value, set];
}

