/** Plafond de la liste d'exceptions de repli (le storage ne grossit jamais sans borne). */
export const MAX_COLLAPSE_EXCEPTIONS = 200;
/** Longueur maximale d'une clé de groupe ou d'une recherche relue. */
const MAX_KEY_LENGTH = 200;
export const MAX_SEARCH_LENGTH = 200;

export function parseGroupMode(raw: string | null): TaskGroupMode {
  return (TASK_GROUP_MODES as readonly string[]).includes(raw ?? '')
    ? (raw as TaskGroupMode)
    : 'project';
}

export function parseStatusFilter(raw: string | null): TaskStatusFilter {
  return (TASK_STATUS_FILTERS as readonly string[]).includes(raw ?? '')
    ? (raw as TaskStatusFilter)
    : 'all';
}

export function serializeString(value: string): string {
