export interface CollapseState {
  /** Intention globale : dernier « Tout replier » (true) ou « Tout déplier » (false). */
  defaultCollapsed: boolean;
  /** Groupes dont l'état diffère de l'intention globale (ordre = ancienneté). */
  exceptions: string[];
}

export const INITIAL_COLLAPSE_STATE: CollapseState = { defaultCollapsed: false, exceptions: [] };

function capExceptions(keys: string[]): string[] {
  return keys.length > MAX_COLLAPSE_EXCEPTIONS
    ? keys.slice(keys.length - MAX_COLLAPSE_EXCEPTIONS)
    : keys;
}

export function parseCollapseState(raw: string | null): CollapseState {
  if (!raw) return INITIAL_COLLAPSE_STATE;
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return INITIAL_COLLAPSE_STATE;
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return INITIAL_COLLAPSE_STATE;
  const record = parsed as Record<string, unknown>;
  if (record.v !== 1 || typeof record.defaultCollapsed !== 'boolean') return INITIAL_COLLAPSE_STATE;
  const rawExceptions = Array.isArray(record.exceptions) ? record.exceptions : [];
  const seen = new Set<string>();
  const exceptions: string[] = [];
  for (const entry of rawExceptions) {
    if (typeof entry !== 'string' || entry.length === 0 || entry.length > MAX_KEY_LENGTH) continue;
    if (seen.has(entry)) continue;
    seen.add(entry);
    exceptions.push(entry);
  }
  return { defaultCollapsed: record.defaultCollapsed, exceptions: capExceptions(exceptions) };
}

export function serializeCollapseState(state: CollapseState): string {
  return JSON.stringify({ v: 1, defaultCollapsed: state.defaultCollapsed, exceptions: state.exceptions });
}

export function isGroupCollapsed(state: CollapseState, key: string): boolean {
  return state.exceptions.includes(key) ? !state.defaultCollapsed : state.defaultCollapsed;
}

export function toggleGroupCollapsed(state: CollapseState, key: string): CollapseState {
  const exceptions = state.exceptions.includes(key)
    ? state.exceptions.filter((entry) => entry !== key)
    : capExceptions([...state.exceptions, key]);
  return { defaultCollapsed: state.defaultCollapsed, exceptions };
}

/** « Tout replier » / « Tout déplier » : nouvelle intention globale, exceptions remises à zéro. */
export function setAllGroupsCollapsed(collapsed: boolean): CollapseState {
  return { defaultCollapsed: collapsed, exceptions: [] };
}

/**
 * Libellé du bouton global pour les groupes VISIBLES : s'il en reste au moins
 * un ouvert, l'action proposée est « Tout replier », sinon « Tout déplier ».
 */
export function nextToggleAllAction(state: CollapseState, visibleKeys: string[]): 'collapse' | 'expand' {
  return visibleKeys.some((key) => !isGroupCollapsed(state, key)) ? 'collapse' : 'expand';
}

/** Clé stable d'un groupe, indépendante de la langue d'affichage. */
export function taskGroupKey(mode: Exclude<TaskGroupMode, 'flat'>, id: string): string {
  return `${mode}:${id}`;
}

